from pathlib import Path

communication_path=Path('js/modules/communication.js')
src=communication_path.read_text(encoding='utf-8')

old_vars="let active='announcements',query='',mounted=false,unsubs=[],openConversationId='',messageRows=[],messageUnsub=null,calendarCursor=new Date(),calendarSelected=new Date().toISOString().slice(0,10),announcementArchive=false,newsSettingsOpen=false;"
new_vars="let active='announcements',query='',mounted=false,unsubs=[],openConversationId='',messageRows=[],messageUnsub=null,calendarCursor=new Date(),calendarSelected=new Date().toISOString().slice(0,10),announcementArchive=false,newsSettingsOpen=false,announcementViewerCleanup=null;"
if old_vars not in src:
    raise RuntimeError('Communication UI state anchor not found')
src=src.replace(old_vars,new_vars,1)

start=src.find('function announcements(){')
end=src.find('\nfunction conversationTitle(k)',start)
if start<0 or end<0:
    raise RuntimeError('Announcements renderer block not found')

replacement=r'''function announcementImages(x){return(Array.isArray(x?.resimler)?x.resimler:[]).map((r,i)=>({...(r||{}),url:safeHref(r?.url),index:i})).filter(r=>r.url)}
function announcementOverlayLock(){document.body.classList.add('ka-announcement-overlay-open')}
function announcementOverlayUnlock(){if(!document.querySelector('[data-announcement-modal],[data-announcement-detail],[data-announcement-lightbox]'))document.body.classList.remove('ka-announcement-overlay-open')}
function closeAnnouncementViewer(){const cleanup=announcementViewerCleanup;announcementViewerCleanup=null;if(typeof cleanup==='function')cleanup();document.querySelector('[data-announcement-lightbox]')?.remove();announcementOverlayUnlock()}
function closeAnnouncementDetail(){closeAnnouncementViewer();document.querySelector('[data-announcement-detail]')?.remove();announcementOverlayUnlock()}
function closeAnnouncementOverlays(){closeAnnouncementViewer();document.querySelector('[data-announcement-detail]')?.remove();document.querySelector('[data-announcement-modal]')?.remove();announcementOverlayUnlock()}
function announcementReaderPanel(x,admin){const readers=announcementReaders(x),readerCount=readers.length;if(!admin)return`<div class="ka-announcement-read-stat"><span>👁</span><b>${readerCount}</b><span>kişi okudu</span></div>`;return`<details class="ka-announcement-readers"><summary><span>👁</span><b>${readerCount}</b><span>kişi okudu</span><span class="ka-announcement-readers__chevron">›</span></summary>${readerCount?`<div class="ka-announcement-readers__list">${readers.map(r=>`<div class="ka-announcement-reader"><span class="ka-announcement-reader__avatar">${esc((r.ad||'?').trim().charAt(0).toLocaleUpperCase('tr')||'?')}</span><strong>${esc(r.ad)}</strong><small>${esc(announcementReadTime(r.tarih))}</small></div>`).join('')}</div>`:'<div class="ka-announcement-readers__empty">Henüz okuyan yok.</div>'}</details>`}
function announcements(){
 const l=arr('duyurular').filter(x=>(announcementArchive?x.arsivlendi===true:x.arsivlendi!==true)&&match([x.baslik,x.icerik,x.aciklama,x.olusturanAdi])).sort((a,b)=>String(b.tarih||'').localeCompare(String(a.tarih||'')));
 const me=uid(),admin=currentUser().admin===true;
 if(!l.length)return{count:0,html:`<div class="ka-announcement-empty"><span aria-hidden="true">📣</span><strong>${announcementArchive?'Arşivde duyuru yok':'Aktif duyuru bulunamadı'}</strong><p>${announcementArchive?'Arşivlenen duyurular burada listelenir.':'Yeni bir duyuru eklendiğinde burada görüntülenir.'}</p></div>`};
 const cards=l.map(x=>{const read=!!x.okuyanlar?.[me],body=announcementText(x),excerpt=body.length>190?body.slice(0,190).trimEnd()+'…':body,images=announcementImages(x),readerView=announcementReaderPanel(x,admin),openAction=(body||images.length)?`<button class="ka-btn ka-btn--secondary ka-announcement-open" type="button" data-announcement-open="${esc(x.id)}"><span>Duyuruyu Aç</span><span aria-hidden="true">›</span></button>`:'';return `<article class="ka-announcement-card ${read?'is-read':'is-new'}" data-announcement-card="${esc(x.id)}"><div class="ka-announcement-card__top"><span class="ka-announcement-card__icon" aria-hidden="true">📣</span><div class="ka-announcement-card__title"><div class="ka-announcement-card__kicker"><span>${announcementArchive?'ARŞİV':'DUYURU'}</span><span>•</span><time>${esc(date(x.tarih)||'Tarih yok')}</time></div><h3>${esc(x.baslik||'Duyuru')}</h3><p>${esc(x.olusturanAdi||'Koruk İlk-Ortaokulu')}</p></div><span class="ka-announcement-status ${read?'is-read':'is-new'}">${read?'✓ Okundu':'● Yeni'}</span></div>${excerpt?`<p class="ka-announcement-card__excerpt">${esc(excerpt)}</p>`:''}${images.length?`<div class="ka-announcement-gallery">${images.slice(0,4).map((r,i)=>`<button type="button" class="ka-announcement-gallery__item" data-announcement-image="${esc(x.id)}" data-announcement-image-index="${i}" aria-label="Duyuru görseli ${i+1} aç"><img src="${esc(r.url)}" alt="Duyuru görseli ${i+1}">${images.length>4&&i===3?`<span>+${images.length-4}</span>`:''}</button>`).join('')}</div>`:''}<div class="ka-announcement-card__insights">${readerView}</div><div class="ka-announcement-card__actions">${openAction}${!read?`<button class="ka-btn ka-announcement-read-button" type="button" data-announcement-read="${esc(x.id)}">✓ Okundu İşaretle</button>`:''}${admin?`<button class="ka-btn ka-btn--secondary" type="button" data-announcement-edit="${esc(x.id)}">Düzenle</button><button class="ka-btn ka-btn--danger" type="button" data-announcement-delete="${esc(x.id)}" data-ka-write="communication.announcements">Sil</button>`:''}</div></article>`}).join('');
 return{count:l.length,html:`<section class="ka-announcement-list">${cards}</section>`}
}
function openAnnouncementImageViewer(item,startIndex=0){const images=announcementImages(item);if(!images.length)return;closeAnnouncementViewer();let index=Math.max(0,Math.min(Number(startIndex)||0,images.length-1));announcementOverlayLock();document.body.insertAdjacentHTML('beforeend',`<div class="ka-announcement-lightbox" data-announcement-lightbox role="dialog" aria-modal="true" aria-label="Duyuru görseli"><header class="ka-announcement-lightbox__header"><div><small>DUYURU GÖRSELLERİ</small><strong>${esc(item.baslik||'Duyuru')}</strong></div><div class="ka-announcement-lightbox__counter" data-announcement-lightbox-counter></div><button class="ka-icon-button" type="button" data-announcement-lightbox-close aria-label="Kapat">×</button></header><div class="ka-announcement-lightbox__stage"><button class="ka-announcement-lightbox__nav is-prev" type="button" data-announcement-lightbox-prev aria-label="Önceki görsel">‹</button><img data-announcement-lightbox-image alt=""><button class="ka-announcement-lightbox__nav is-next" type="button" data-announcement-lightbox-next aria-label="Sonraki görsel">›</button></div>${images.length>1?`<footer class="ka-announcement-lightbox__thumbs">${images.map((r,i)=>`<button type="button" data-announcement-lightbox-thumb="${i}" aria-label="${i+1}. görsel"><img src="${esc(r.url)}" alt=""></button>`).join('')}</footer>`:''}</div>`);const box=document.querySelector('[data-announcement-lightbox]'),img=box?.querySelector('[data-announcement-lightbox-image]'),counter=box?.querySelector('[data-announcement-lightbox-counter]'),prev=box?.querySelector('[data-announcement-lightbox-prev]'),next=box?.querySelector('[data-announcement-lightbox-next]');const paint=()=>{const current=images[index];if(img){img.src=current.url;img.alt=`${item.baslik||'Duyuru'} — görsel ${index+1}`}if(counter)counter.textContent=`${index+1} / ${images.length}`;if(prev)prev.disabled=index===0;if(next)next.disabled=index===images.length-1;box?.querySelectorAll('[data-announcement-lightbox-thumb]').forEach(b=>b.classList.toggle('is-active',Number(b.dataset.announcementLightboxThumb)===index))};const close=()=>closeAnnouncementViewer();box?.querySelector('[data-announcement-lightbox-close]')?.addEventListener('click',close);box?.addEventListener('click',e=>{if(e.target===box)close()});prev?.addEventListener('click',()=>{if(index>0){index--;paint()}});next?.addEventListener('click',()=>{if(index<images.length-1){index++;paint()}});box?.querySelectorAll('[data-announcement-lightbox-thumb]').forEach(b=>b.addEventListener('click',()=>{index=Number(b.dataset.announcementLightboxThumb)||0;paint()}));const onKey=e=>{if(e.key==='Escape')close();else if(e.key==='ArrowLeft'&&index>0){index--;paint()}else if(e.key==='ArrowRight'&&index<images.length-1){index++;paint()}};document.addEventListener('keydown',onKey);announcementViewerCleanup=()=>document.removeEventListener('keydown',onKey);paint()}
function openAnnouncementDetail(item){if(!item)return;closeAnnouncementDetail();const admin=currentUser().admin===true,read=!!item.okuyanlar?.[uid()],body=announcementText(item),images=announcementImages(item),readerPanel=announcementReaderPanel(item,admin);announcementOverlayLock();document.body.insertAdjacentHTML('beforeend',`<div class="ka-announcement-detail-backdrop" data-announcement-detail><article class="ka-announcement-detail" role="dialog" aria-modal="true" aria-labelledby="announcementDetailTitle"><header class="ka-announcement-detail__header"><div class="ka-announcement-detail__identity"><span aria-hidden="true">📣</span><div><small>${item.arsivlendi?'ARŞİV DUYURUSU':'OKUL DUYURUSU'}</small><h2 id="announcementDetailTitle">${esc(item.baslik||'Duyuru')}</h2><p>${esc(item.olusturanAdi||'Koruk İlk-Ortaokulu')} · ${esc(date(item.tarih)||'Tarih yok')}</p></div></div><button class="ka-icon-button" type="button" data-announcement-detail-close aria-label="Kapat">×</button></header><div class="ka-announcement-detail__body"><div class="ka-announcement-detail__status"><span class="ka-announcement-status ${read?'is-read':'is-new'}" data-announcement-detail-status>${read?'✓ Okundu':'● Yeni'}</span>${item.arsivlendi?'<span class="ka-badge">Arşivde</span>':''}</div>${body?`<article class="ka-announcement-detail__message">${esc(body)}</article>`:'<div class="ka-announcement-detail__empty">Bu duyuruda metin bulunmuyor.</div>'}${images.length?`<section class="ka-announcement-detail__gallery"><div class="ka-announcement-detail__section-title"><strong>Görseller</strong><small>${images.length} görsel</small></div><button type="button" class="ka-announcement-detail__hero-image" data-announcement-detail-image="0"><img src="${esc(images[0].url)}" alt="Duyuru görseli 1"><span>🔍 Görseli büyüt</span></button>${images.length>1?`<div class="ka-announcement-detail__thumbs">${images.slice(1).map((r,i)=>`<button type="button" data-announcement-detail-image="${i+1}" aria-label="Duyuru görseli ${i+2} aç"><img src="${esc(r.url)}" alt="Duyuru görseli ${i+2}"></button>`).join('')}</div>`:''}</section>`:''}<section class="ka-announcement-detail__readers"><div class="ka-announcement-detail__section-title"><strong>Okunma Bilgisi</strong><small>Duyurunun erişim durumu</small></div>${readerPanel}</section></div><footer class="ka-announcement-detail__footer">${!read?`<button class="ka-btn" type="button" data-announcement-detail-read="${esc(item.id)}">✓ Okundu İşaretle</button>`:''}${admin?`<button class="ka-btn ka-btn--secondary" type="button" data-announcement-detail-edit="${esc(item.id)}">Düzenle</button>`:''}<button class="ka-btn ka-btn--secondary" type="button" data-announcement-detail-close>Kapat</button></footer></article></div>`);const overlay=document.querySelector('[data-announcement-detail]'),close=()=>closeAnnouncementDetail();overlay?.querySelectorAll('[data-announcement-detail-close]').forEach(b=>b.addEventListener('click',close));overlay?.addEventListener('click',e=>{if(e.target===overlay)close()});overlay?.querySelectorAll('[data-announcement-detail-image]').forEach(b=>b.addEventListener('click',()=>openAnnouncementImageViewer(item,Number(b.dataset.announcementDetailImage)||0)));overlay?.querySelector('[data-announcement-detail-edit]')?.addEventListener('click',()=>{close();openAnnouncementModal(item)});overlay?.querySelector('[data-announcement-detail-read]')?.addEventListener('click',async e=>{const button=e.currentTarget;button.disabled=true;try{await globalThis.DuyurularService?.okunduIsaretle?.(item.id);overlay?.querySelector('[data-announcement-detail-status]')?.classList.remove('is-new');const status=overlay?.querySelector('[data-announcement-detail-status]');if(status){status.classList.add('is-read');status.textContent='✓ Okundu'}button.remove();safeToast('Duyuru okundu olarak işaretlendi.');render()}catch(err){button.disabled=false;safeToast(err?.message||'Duyuru güncellenemedi.')}})}'''

src=src[:start]+replacement+src[end:]

modal_anchor="function openAnnouncementModal(item={}){\n document.querySelector('[data-announcement-modal]')?.remove();"
if modal_anchor not in src:
    raise RuntimeError('Announcement modal anchor not found')
src=src.replace(modal_anchor,"function openAnnouncementModal(item={}){\n document.querySelector('[data-announcement-modal]')?.remove();\n announcementOverlayLock();",1)
old_close="const modal=document.querySelector('[data-announcement-modal]'),close=()=>modal?.remove(),status=modal?.querySelector('[data-announcement-upload]')"
new_close="const modal=document.querySelector('[data-announcement-modal]'),close=()=>{modal?.remove();announcementOverlayUnlock()},status=modal?.querySelector('[data-announcement-upload]')"
if old_close not in src:
    raise RuntimeError('Announcement modal close anchor not found')
src=src.replace(old_close,new_close,1)

bind_anchor=" out.querySelectorAll('[data-announcement-edit]').forEach(b=>b.addEventListener('click',()=>{const item=arr('duyurular').find(x=>x.id===b.dataset.announcementEdit);if(item)openAnnouncementModal(item)}));"
if bind_anchor not in src:
    raise RuntimeError('Announcement action binding anchor not found')
bind_extra=bind_anchor+"\n out.querySelectorAll('[data-announcement-open]').forEach(b=>b.addEventListener('click',()=>{const item=arr('duyurular').find(x=>x.id===b.dataset.announcementOpen);if(item)openAnnouncementDetail(item)}));\n out.querySelectorAll('[data-announcement-image]').forEach(b=>b.addEventListener('click',()=>{const item=arr('duyurular').find(x=>x.id===b.dataset.announcementImage);if(item)openAnnouncementImageViewer(item,Number(b.dataset.announcementImageIndex)||0)}));"
src=src.replace(bind_anchor,bind_extra,1)

old_open_page="function openPage(page,title=''){const allowed=['announcements','messages','polls','news','notes','calendar'];if(!allowed.includes(page))return false;if(active==='messages'&&page!=='messages')closeMessageConversation(false);active=page;query='';const h=document.querySelector('[data-communication-module] > .ka-row h2');if(h&&title)h.textContent=title;render();return true}"
new_open_page="function openPage(page,title=''){const allowed=['announcements','messages','polls','news','notes','calendar'];if(!allowed.includes(page))return false;if(active==='messages'&&page!=='messages')closeMessageConversation(false);if(page!=='announcements')closeAnnouncementOverlays();active=page;query='';const h=document.querySelector('[data-communication-module] > .ka-row h2');if(h&&title)h.textContent=title;render();return true}"
if old_open_page not in src:
    raise RuntimeError('Communication openPage anchor not found')
src=src.replace(old_open_page,new_open_page,1)
old_unmount="function unmount(){mounted=false;closeMessageConversation(false);document.querySelector('[data-new-message-modal]')?.remove();document.querySelector('[data-note-modal]')?.remove();document.querySelector('[data-note-detail]')?.remove();document.querySelector('[data-cal-modal]')?.remove();unsubs.forEach(f=>{try{f()}catch(_){}});unsubs=[]}"
new_unmount="function unmount(){mounted=false;closeMessageConversation(false);closeAnnouncementOverlays();document.querySelector('[data-new-message-modal]')?.remove();document.querySelector('[data-note-modal]')?.remove();document.querySelector('[data-note-detail]')?.remove();document.querySelector('[data-cal-modal]')?.remove();unsubs.forEach(f=>{try{f()}catch(_){}});unsubs=[]}"
if old_unmount not in src:
    raise RuntimeError('Communication unmount anchor not found')
src=src.replace(old_unmount,new_unmount,1)
communication_path.write_text(src,encoding='utf-8')

css_path=Path('css/design-system.css')
css=css_path.read_text(encoding='utf-8')
marker='/* Announcements detail + in-app image viewer — canonical communication layer. */'
if marker in css:
    raise RuntimeError('Announcement detail CSS already exists')
css += r'''
/* Announcements detail + in-app image viewer — canonical communication layer. */
body.ka-announcement-overlay-open{overflow:hidden}
.ka-announcement-open{margin-right:auto}.ka-announcement-open>span:last-child{font-size:19px;line-height:1}
button.ka-announcement-gallery__item{appearance:none;padding:0;border:1px solid var(--ka-border);cursor:zoom-in;color:inherit;text-align:inherit;font:inherit}
.ka-announcement-detail-backdrop{position:fixed;inset:0;z-index:2400;display:grid;place-items:center;padding:22px;background:var(--ka-overlay);backdrop-filter:blur(8px)}
.ka-announcement-detail{width:min(780px,100%);max-height:min(920px,92dvh);display:flex;flex-direction:column;overflow:hidden;border:1px solid var(--ka-border);border-radius:26px;background:var(--ka-card-bg);box-shadow:var(--ka-shadow-modal);color:var(--ka-text)}
.ka-announcement-detail__header{flex:0 0 auto;display:flex;align-items:flex-start;justify-content:space-between;gap:14px;padding:20px 22px;border-bottom:1px solid var(--ka-border);background:linear-gradient(145deg,var(--ka-card-raised-bg),var(--ka-card-bg))}
.ka-announcement-detail__identity{display:grid;grid-template-columns:48px minmax(0,1fr);gap:13px;align-items:start;min-width:0}.ka-announcement-detail__identity>span{width:48px;height:48px;border-radius:15px;display:grid;place-items:center;background:var(--ka-primary-soft);font-size:23px}.ka-announcement-detail__identity small{display:block;color:var(--ka-primary);font-size:10px;font-weight:850;letter-spacing:.08em}.ka-announcement-detail__identity h2{margin-top:3px;font-size:clamp(22px,4vw,30px);line-height:1.18;letter-spacing:-.025em}.ka-announcement-detail__identity p{margin-top:5px;color:var(--ka-text-muted);font-size:12px}
.ka-announcement-detail__body{flex:1 1 auto;min-height:0;overflow:auto;padding:20px 22px;display:grid;gap:20px}.ka-announcement-detail__status{display:flex;align-items:center;gap:8px;flex-wrap:wrap}
.ka-announcement-detail__message{padding:18px;border:1px solid var(--ka-border);border-radius:17px;background:var(--ka-muted-bg);white-space:pre-wrap;font-size:15px;line-height:1.7}.ka-announcement-detail__empty{padding:18px;border:1px dashed var(--ka-border-strong);border-radius:17px;color:var(--ka-text-muted);text-align:center}
.ka-announcement-detail__section-title{display:flex;align-items:end;justify-content:space-between;gap:10px;margin-bottom:10px}.ka-announcement-detail__section-title strong{font-size:15px}.ka-announcement-detail__section-title small{color:var(--ka-text-muted);font-size:11px}
.ka-announcement-detail__hero-image{position:relative;width:100%;max-height:420px;min-height:210px;padding:0;overflow:hidden;border:1px solid var(--ka-border);border-radius:18px;background:var(--ka-muted-bg);cursor:zoom-in}.ka-announcement-detail__hero-image img{width:100%;height:100%;max-height:420px;min-height:210px;display:block;object-fit:contain}.ka-announcement-detail__hero-image>span{position:absolute;right:12px;bottom:12px;min-height:34px;padding:6px 10px;border-radius:10px;background:rgba(5,18,13,.72);color:#fff;display:inline-flex;align-items:center;font-size:11px;font-weight:800}
.ka-announcement-detail__thumbs{display:grid;grid-template-columns:repeat(auto-fill,minmax(88px,1fr));gap:8px;margin-top:8px}.ka-announcement-detail__thumbs button{aspect-ratio:1.25;padding:0;overflow:hidden;border:1px solid var(--ka-border);border-radius:12px;background:var(--ka-muted-bg);cursor:zoom-in}.ka-announcement-detail__thumbs img{width:100%;height:100%;display:block;object-fit:cover}
.ka-announcement-detail__readers .ka-announcement-readers,.ka-announcement-detail__readers .ka-announcement-read-stat{width:100%}
.ka-announcement-detail__footer{flex:0 0 auto;display:flex;justify-content:flex-end;align-items:center;gap:9px;flex-wrap:wrap;padding:14px 22px calc(14px + var(--ka-safe-bottom));border-top:1px solid var(--ka-border);background:var(--ka-card-raised-bg)}.ka-announcement-detail__footer .ka-btn{min-width:120px}
.ka-announcement-lightbox{position:fixed;inset:0;z-index:2600;display:grid;grid-template-rows:auto minmax(0,1fr) auto;background:rgba(2,8,6,.96);color:#fff;backdrop-filter:blur(12px)}
.ka-announcement-lightbox__header{display:grid;grid-template-columns:minmax(0,1fr) auto 44px;align-items:center;gap:12px;padding:calc(12px + var(--ka-safe-top)) max(14px,var(--ka-safe-right)) 12px max(14px,var(--ka-safe-left));border-bottom:1px solid rgba(255,255,255,.12)}.ka-announcement-lightbox__header>div:first-child{min-width:0;display:grid}.ka-announcement-lightbox__header small{color:#83e5bd;font-size:9px;font-weight:850;letter-spacing:.09em}.ka-announcement-lightbox__header strong{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:#fff;font-size:14px}.ka-announcement-lightbox__header .ka-icon-button{color:#fff;background:rgba(255,255,255,.08)}.ka-announcement-lightbox__counter{min-width:54px;padding:6px 9px;border-radius:999px;background:rgba(255,255,255,.09);font-size:11px;font-weight:800;text-align:center}
.ka-announcement-lightbox__stage{position:relative;min-height:0;display:grid;place-items:center;padding:18px 62px}.ka-announcement-lightbox__stage>img{max-width:100%;max-height:100%;width:auto;height:auto;object-fit:contain;border-radius:8px;box-shadow:0 20px 60px rgba(0,0,0,.35)}.ka-announcement-lightbox__nav{position:absolute;top:50%;transform:translateY(-50%);width:46px;height:58px;border:1px solid rgba(255,255,255,.14);border-radius:15px;background:rgba(255,255,255,.09);color:#fff;font-size:34px;display:grid;place-items:center;cursor:pointer}.ka-announcement-lightbox__nav.is-prev{left:10px}.ka-announcement-lightbox__nav.is-next{right:10px}.ka-announcement-lightbox__nav:disabled{opacity:.2;cursor:default}
.ka-announcement-lightbox__thumbs{display:flex;justify-content:center;gap:8px;overflow-x:auto;padding:10px max(14px,var(--ka-safe-right)) calc(12px + var(--ka-safe-bottom)) max(14px,var(--ka-safe-left));border-top:1px solid rgba(255,255,255,.12);scrollbar-width:none}.ka-announcement-lightbox__thumbs::-webkit-scrollbar{display:none}.ka-announcement-lightbox__thumbs button{flex:0 0 62px;width:62px;height:52px;padding:2px;border:2px solid transparent;border-radius:10px;background:rgba(255,255,255,.08);overflow:hidden;cursor:pointer}.ka-announcement-lightbox__thumbs button.is-active{border-color:#53d6a4}.ka-announcement-lightbox__thumbs img{width:100%;height:100%;display:block;object-fit:cover;border-radius:6px}
@media(max-width:700px){.ka-announcement-detail-backdrop{padding:0;place-items:stretch}.ka-announcement-detail{width:100%;height:100dvh;max-height:none;border:0;border-radius:0}.ka-announcement-detail__header{padding:calc(14px + var(--ka-safe-top)) 16px 14px}.ka-announcement-detail__identity{grid-template-columns:42px minmax(0,1fr);gap:10px}.ka-announcement-detail__identity>span{width:42px;height:42px;border-radius:13px}.ka-announcement-detail__identity h2{font-size:21px}.ka-announcement-detail__body{padding:16px;gap:16px}.ka-announcement-detail__message{padding:15px;font-size:14px}.ka-announcement-detail__hero-image,.ka-announcement-detail__hero-image img{min-height:190px;max-height:330px}.ka-announcement-detail__footer{position:sticky;bottom:0;padding:10px 16px calc(10px + var(--ka-safe-bottom));display:grid;grid-template-columns:repeat(2,minmax(0,1fr))}.ka-announcement-detail__footer .ka-btn{min-width:0}.ka-announcement-detail__footer .ka-btn:first-child:last-child{grid-column:1/-1}.ka-announcement-lightbox__stage{padding:14px 46px}.ka-announcement-lightbox__nav{width:38px;height:52px;border-radius:12px;font-size:28px}.ka-announcement-lightbox__nav.is-prev{left:5px}.ka-announcement-lightbox__nav.is-next{right:5px}}
'''
